#!/usr/bin/env python3
"""Strict CSV-to-records, records-to-CSV, and CSV-to-JSON utilities."""

from __future__ import annotations

from collections.abc import Iterable, Mapping
import csv
import io
import json
import sys
from typing import Any

_HEADER = ["name", "note"]


def _validate_csv_quoting(text: str) -> None:
    """Reject quotes that do not follow CSV field-quoting rules."""
    FIELD_START = 0
    UNQUOTED = 1
    QUOTED = 2
    AFTER_QUOTE = 3

    state = FIELD_START
    index = 0
    length = len(text)

    while index < length:
        char = text[index]

        if state == QUOTED:
            if char == '"':
                if index + 1 < length and text[index + 1] == '"':
                    index += 2
                    continue
                state = AFTER_QUOTE
            index += 1
            continue

        if char == "\r" or char == "\n":
            if char == "\r" and index + 1 < length and text[index + 1] == "\n":
                index += 2
            else:
                index += 1
            state = FIELD_START
            continue

        if state == FIELD_START:
            if char == '"':
                state = QUOTED
            elif char == ",":
                state = FIELD_START
            else:
                state = UNQUOTED
        elif state == UNQUOTED:
            if char == '"':
                raise ValueError("malformed CSV: quote inside an unquoted field")
            if char == ",":
                state = FIELD_START
        else:
            if char == ",":
                state = FIELD_START
            else:
                raise ValueError("malformed CSV: unexpected character after closing quote")

        index += 1

    if state == QUOTED:
        raise ValueError("malformed CSV: unterminated quoted field")


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV with the exact header name,note into record dictionaries."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_csv_quoting(text)
    stream = io.StringIO(text, newline="")
    try:
        reader = csv.reader(stream, strict=True)
        header = next(reader, None)
        if header != _HEADER:
            raise ValueError("CSV header must be exactly name,note")

        records: list[dict[str, str]] = []
        for row_number, row in enumerate(reader, start=2):
            if len(row) != 2:
                raise ValueError(
                    f"CSV row {row_number} has {len(row)} columns; expected 2"
                )
            records.append({"name": row[0], "note": row[1]})
        return records
    except csv.Error as exc:
        raise ValueError(f"malformed CSV: {exc}") from None


def format_records(records: Iterable[Mapping[str, Any]]) -> str:
    """Serialize valid name/note records as CSV using LF line terminators."""
    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of mappings") from None

    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    for record_number, record in enumerate(iterator, start=1):
        if not isinstance(record, Mapping):
            raise ValueError(f"record {record_number} must be a mapping")
        try:
            keys = set(record.keys())
        except (AttributeError, TypeError):
            raise ValueError(f"record {record_number} must have string keys") from None
        if keys != {"name", "note"}:
            raise ValueError(
                f"record {record_number} must contain exactly name and note"
            )
        try:
            name = record["name"]
            note = record["note"]
        except (KeyError, TypeError):
            raise ValueError(
                f"record {record_number} must contain exactly name and note"
            ) from None
        if not isinstance(name, str) or not isinstance(note, str):
            raise ValueError(f"record {record_number} values must be strings")
        writer.writerow([name, note])

    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid CSV text to JSON without altering field strings."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    try:
        text = sys.stdin.read()
        result = to_json(text)
    except (ValueError, UnicodeError) as exc:
        print(f"csv_tool.py: {exc}", file=sys.stderr)
        return 2

    sys.stdout.write(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
